insert into public.lessons (id, module_id, title, summary, sort_order, status) values
  ('3b939bd8-1328-58a9-981b-626e5846e524', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'The Eight Steps at a Glance', 'Memorise the order. Improvise the words.', 0, 'published'),
  ('52f8509a-2290-58ce-acf0-18717d1196ae', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 1 - Greet', 'Warm, clear, and identical every time.', 1, 'published'),
  ('acb4d277-b71e-5bbd-aae5-8a59a10567b9', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 2 - Introduce', 'Confirm the person, then place yourself.', 2, 'published'),
  ('1f9daf84-a6e6-55e8-b6ec-d99f7d0ec41f', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 3 - Purpose', 'Say why you called, then ask permission for the time.', 3, 'published'),
  ('9dccfe1c-41d1-5f07-b303-4127234a3f8d', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 4 - Discover', 'The step that makes every later step easier.', 4, 'published'),
  ('e84d866e-0ce0-5159-8563-a83e1f0a1be3', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 5 - Present', 'One recommendation, connected to what they told you.', 5, 'published'),
  ('6e2efdd8-4918-5de3-bc6e-7f8379f8bb5c', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 6 - Handle Objection', 'A.C.A.C. - the same four moves for every objection.', 6, 'published'),
  ('571b4028-108a-5f04-9cc9-3d54d27c6423', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 7 - Close', 'Ask for something small, specific, and dated.', 7, 'published'),
  ('76b3d2ae-baa6-5b6c-bf61-59f943908c48', '5efb088e-d8f8-5aad-8a27-bfde6c834c98', 'Step 8 - Confirm + End', 'Recap, state next steps, thank them by name.', 8, 'published')
